CREATE TABLE `job_postings_fact` (
  `job_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `job_title_short` varchar(100) DEFAULT NULL,
  `job_title` varchar(250) DEFAULT NULL,
  `job_location` varchar(100) DEFAULT NULL,
  `job_via` varchar(100) DEFAULT NULL,
  `job_schedule_type` varchar(250) DEFAULT NULL,
  `job_work_from_home` int DEFAULT NULL,
  `search_location` varchar(250) DEFAULT NULL,
  `job_posted_date` timestamp NULL DEFAULT NULL,
  `job_no_degree_mention` int DEFAULT NULL,
  `job_health_insurance` int DEFAULT NULL,
  `job_country` varchar(150) DEFAULT NULL,
  `salary_rate` varchar(100) DEFAULT NULL,
  `salary_year_avg` decimal(10,2) DEFAULT NULL,
  `salary_hour_avg` int DEFAULT NULL,
  PRIMARY KEY (`job_id`),
  KEY `company_id` (`company_id`),
  CONSTRAINT `job_postings_fact_ibfk_1` FOREIGN KEY (`company_id`) REFERENCES `company_dim` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
